definition:
agentflow-beta TB
  brief["Release brief"]@{ shape: input }
  review["Check changes"]@{ shape: task }
  ready["Publish notes"]@{ shape: task }
  brief --> review --> ready

classDiagram
  class Order {
    +String number
    +confirm()
  }
  class Parcel {
    +String trackingCode
  }
  Order "1" *-- "*" Parcel : ships

erDiagram
  BUYER ||--o{ ORDER : places
  ORDER ||--|{ PARCEL : contains
  ORDER {
    int id PK
    date placed_at
  }
  PARCEL {
    string tracking_code PK
  }

railroad-ebnf-beta
  choice = "ship" | "hold" ;
  request = choice ":" identifier ;

requirementDiagram
  requirement TrackParcel {
    id: 1
    text: Show parcel status
    risk: medium
    verifymethod: test
  }
  element TrackingView {
    type: web page
  }
  TrackingView - satisfies -> TrackParcel
